import{_ as i,C as n,o as l,c as g,a6 as a,E as r,j as e,a as s}from"./chunks/framework.CrjICMdL.js";const c="/rb_cobot_docs_muscat/images/program/vision-form.avif",h="/rb_cobot_docs_muscat/images/program/vision-read.avif",I=JSON.parse('{"title":"비전","description":"","frontmatter":{"title":"비전","outline":[2,3]},"headers":[],"relativePath":"manual/program/vision.md","filePath":"manual/program/vision.md","lastUpdated":1792552919000}'),p={name:"manual/program/vision.md"};function m(b,t,_,x,u,y){const o=n("DemoFrame"),d=n("ScenarioSteps");return l(),g("div",null,[t[0]||(t[0]=a('<h1 id="비전" tabindex="-1">비전 <a class="header-anchor" href="#비전" aria-label="Permalink to &quot;비전&quot;">​</a></h1><p><strong>비전</strong>은 프로그램에서 <strong>3D 비전 카메라(비전 서버)와 통신</strong>하는 명령입니다. 카메라에 연결하고, 촬영을 요청하고, 인식한 물체의 위치를 읽어 오는 일을 프로그램 안에서 할 수 있습니다. 읽은 위치는 변수에 저장되므로 뒤의 동작 명령에서 쓸 수 있습니다.</p><p>이 문서에서는 <strong>프로그램</strong> 화면에서 다음을 해 봅니다.</p><ul><li>비전 명령으로 카메라 연결 만들기</li><li>두 번째 비전 명령으로 촬영하고 물체 위치 읽기</li><li>연결할 수 있는 비전 시스템 확인하기</li></ul><div class="tip custom-block"><p class="custom-block-title">실습에서 확인할 수 있는 것</p><p>실습 화면에는 카메라가 없어 설정만 해 볼 수 있습니다. 프로그램을 실행했을 때의 카메라 응답은 확인할 수 없습니다.</p></div><h2 id="비전-시스템" tabindex="-1">비전 시스템 <a class="header-anchor" href="#비전-시스템" aria-label="Permalink to &quot;비전 시스템&quot;">​</a></h2><p>설정 화면의 <strong>옵션</strong>에서 연결할 비전 시스템을 고릅니다. 고른 시스템에 맞는 설정 항목이 아래에 나타납니다.</p><table tabindex="0"><thead><tr><th>옵션</th><th style="text-align:center;">기본 포트</th><th>하는 일(함수 목록에서 고름)</th></tr></thead><tbody><tr><td><strong>MechMind 3D</strong></td><td style="text-align:center;">50000</td><td>연결 생성, 레시피 설정, 트리거, 트리거 &amp; 자세 읽기, 자세 읽기</td></tr><tr><td><strong>Photoneo</strong></td><td style="text-align:center;">11003</td><td>연결 생성, 초기화, 스캔, 오브젝트 위치 조회, 궤적 조회, 솔루션 변경·시작·정지·조회, 궤적 이동</td></tr><tr><td><strong>PICKIT 3D</strong></td><td style="text-align:center;">50</td><td>연결 생성, 로봇 자세 업데이트, 모드 확인, 시스템 종료, 캘리브레이션 플레이트 찾기·설정·계산·검증, 객체 탐색, 재시도 객체 탐색, 다음 객체, 이미지 캡처·처리, 피킹 포인트 데이터 가져오기, 셋업 및 제품 설정, 실린더 치수 설정, 활성 셋업·제품 저장, 배경 생성, 스냅샷 저장</td></tr></tbody></table><p>이 문서는 처음 골라져 있는 <strong>MechMind 3D</strong>를 자세히 설명합니다. 다른 시스템도 같은 구조입니다. 목표 서버 IP 주소와 포트 번호, 함수 목록에서 고르는 기능, 기능별 설정 영역으로 이루어집니다.</p><h2 id="mechmind-3d-설정-화면" tabindex="-1">MechMind 3D 설정 화면 <a class="header-anchor" href="#mechmind-3d-설정-화면" aria-label="Permalink to &quot;MechMind 3D 설정 화면&quot;">​</a></h2><p>함수 목록이 <strong>연결 생성</strong>일 때의 화면입니다. 목표 서버 IP 주소에 <code>192.168.0.10</code>, 타임 아웃에 10을 입력한 상태입니다.</p><p><img src="'+c+'" alt="비전 설정 화면(MechMind 3D 연결 생성)"></p><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th style="text-align:center;">번호</th><th>항목</th><th>설명</th></tr></thead><tbody><tr><td style="text-align:center;">①</td><td><strong>옵션</strong></td><td>연결할 비전 시스템(MechMind 3D·Photoneo·PICKIT 3D)입니다.</td></tr><tr><td style="text-align:center;">②</td><td><strong>목표 서버 IP 주소</strong></td><td>카메라(비전 서버)의 IP 주소입니다. 네 칸에 나누어 입력하며 모두 입력해야 저장할 수 있습니다.</td></tr><tr><td style="text-align:center;">③</td><td><strong>목표 서버 포트 번호</strong></td><td>MechMind 3D는 50000으로 정해져 있어 바꿀 수 없습니다.</td></tr><tr><td style="text-align:center;">④</td><td><strong>함수 목록 (코드)</strong></td><td>이 명령이 하는 일입니다. 연결 생성(99), 레시피 설정(3), 트리거(1), 트리거 &amp; 자세 읽기(0), 자세 읽기(2) 중에서 고릅니다.</td></tr><tr><td style="text-align:center;">⑤</td><td><strong>타임 아웃 (초)</strong></td><td>카메라의 응답을 기다리는 시간입니다.</td></tr><tr><td style="text-align:center;">⑥</td><td><strong>설치 위치</strong></td><td>카메라를 로봇 손에 달았는지(<strong>Eye In Hand</strong>), 로봇 밖에 고정했는지(<strong>Eye To Hand</strong>)입니다.</td></tr><tr><td style="text-align:center;">⑦</td><td><strong>Project ID</strong></td><td>카메라 소프트웨어의 프로젝트 번호입니다. 비워 둘 수 있고, 입력하면 정수여야 합니다(&quot;Integer only&quot;).</td></tr><tr><td style="text-align:center;">⑧</td><td><strong>실패 처리 방식</strong></td><td>카메라와의 통신이 실패했을 때의 동작입니다. <strong>무시 후 진행</strong>, <strong>즉시 중단</strong>, <strong>사용자 확인</strong> 중에서 고르며 처음에는 무시 후 진행입니다.</td></tr><tr><td style="text-align:center;">⑨</td><td><strong>닫기</strong></td><td>설정 화면을 닫습니다. 저장하지 않은 변경이 있으면 저장하지 않고 닫을지 묻습니다.</td></tr><tr><td style="text-align:center;">⑩</td><td><strong>저장</strong></td><td>설정을 적용합니다. 트리의 비전 옆에 <code>MechMind Interface - [Create Connection] 192.168.0.10:50000</code>처럼 표시됩니다.</td></tr></tbody></table></div><h3 id="함수-목록별-설정" tabindex="-1">함수 목록별 설정 <a class="header-anchor" href="#함수-목록별-설정" aria-label="Permalink to &quot;함수 목록별 설정&quot;">​</a></h3><p>함수 목록을 바꾸면 ⑦ 아래의 설정 영역이 바뀝니다.</p><table tabindex="0"><thead><tr><th>함수</th><th>아래 설정 영역의 항목</th><th>하는 일</th></tr></thead><tbody><tr><td><strong>연결 생성</strong></td><td>Project ID, 실패 처리 방식</td><td>카메라에 연결합니다. 같은 태스크에서 다시 연결 생성을 실행하면 이전 연결을 끊고 새로 연결합니다.</td></tr><tr><td><strong>레시피 설정</strong></td><td>Project ID, Recipe ID, 실패 처리 방식</td><td>프로젝트에서 사용할 레시피를 바꿉니다.</td></tr><tr><td><strong>트리거</strong></td><td>Project ID, 예상 수, 실패 처리 방식</td><td>촬영과 인식을 요청합니다. 예상 수는 인식하려는 물체의 예상 개수입니다. 결과 위치는 자세 읽기로 따로 읽습니다.</td></tr><tr><td><strong>트리거 &amp; 자세 읽기</strong></td><td>Project ID, 반환 변수명, 실패 처리 방식</td><td>촬영·인식을 요청하고 인식한 물체의 위치 목록을 한 번에 읽어 <strong>반환 변수명</strong>의 변수에 저장합니다.</td></tr><tr><td><strong>자세 읽기</strong></td><td>Project ID, 반환 변수명, 실패 처리 방식</td><td>새로 촬영하지 않고 <strong>가장 최근 트리거</strong>의 결과 위치를 읽어 변수에 저장합니다.</td></tr></tbody></table><p>읽은 위치는 <code>[x, y, z, rx, ry, rz]</code> 형태의 값을 담은 목록입니다. 촬영할 때 설치 위치가 <strong>Eye In Hand</strong>이면 로봇의 현재 자세를 카메라 소프트웨어에 함께 보내 위치를 보정하고, <strong>Eye To Hand</strong>이면 로봇 자세를 보내지 않습니다.</p><div class="warning custom-block"><p class="custom-block-title">연결 생성 먼저</p><p>트리거·자세 읽기 같은 함수는 앞에서 <strong>연결 생성</strong>이 실행되어 연결되어 있어야 동작합니다. 연결 생성이 아닌 함수를 고르면 목표 서버 IP 주소·포트·타임 아웃·설치 위치를 바꿀 수 없고, 앞의 연결 생성 비전 명령에서 정한 값을 따릅니다.</p></div><h3 id="읽기-설정" tabindex="-1">읽기 설정 <a class="header-anchor" href="#읽기-설정" aria-label="Permalink to &quot;읽기 설정&quot;">​</a></h3><p>함수 목록을 <strong>트리거 &amp; 자세 읽기</strong>로 고른 화면의 읽기 설정 영역입니다.</p><p><img src="'+h+'" alt="트리거 &amp; 자세 읽기의 읽기 설정"></p><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th style="text-align:center;">번호</th><th>항목</th><th>설명</th></tr></thead><tbody><tr><td style="text-align:center;">①</td><td><strong>Project ID</strong></td><td>읽을 프로젝트 번호입니다. 비워 둘 수 있습니다.</td></tr><tr><td style="text-align:center;">②</td><td><strong>반환 변수명</strong></td><td>읽은 위치 목록을 저장할 변수 이름입니다. 비워 두면 저장할 수 없습니다.</td></tr><tr><td style="text-align:center;">③</td><td><strong>실패 처리 방식</strong></td><td>연결 생성과 같습니다.</td></tr></tbody></table></div><h2 id="직접-해-보기" tabindex="-1">직접 해 보기 <a class="header-anchor" href="#직접-해-보기" aria-label="Permalink to &quot;직접 해 보기&quot;">​</a></h2><p>비전 명령을 두 개 만들어 카메라 연결 생성과 물체 위치 읽기를 설정해 봅니다. 실습에는 실제 카메라가 없으며 프로그램을 실행하지 않습니다. 실습은 두 가지이며 어느 쪽부터 해도 되고, 앞의 실습을 하지 않아도 시작할 수 있습니다. 실습을 다시 시작하면 바꾼 값은 처음 상태로 돌아갑니다.</p><h3 id="카메라-연결-만들기" tabindex="-1">카메라 연결 만들기 <a class="header-anchor" href="#카메라-연결-만들기" aria-label="Permalink to &quot;카메라 연결 만들기&quot;">​</a></h3><p>비전을 추가하고 MechMind 3D의 연결 생성을 설정하는 과정입니다.</p><ol><li>트리의 빈 영역을 눌러 위치를 정하고 편집 아이콘으로 명령어 목록을 연 뒤 <strong>비전</strong>을 추가합니다.</li><li>트리에서 비전을 눌러 설정 화면을 열고, MechMind 3D의 연결 생성 설정을 확인합니다.</li><li>목표 서버 IP 주소의 네 칸에 <code>192</code>, <code>168</code>, <code>0</code>, <code>10</code>을, 타임 아웃에 <code>10</code>을 입력합니다. 입력한 값이 안내와 같아야 다음으로 넘어갈 수 있으며, 건너뛰면 자동으로 입력됩니다.</li><li><strong>저장</strong>을 누르면 트리의 비전 옆에 <code>[Create Connection]</code>과 주소가 표시됩니다.</li></ol>',27)),r(o,{id:"program-vision-connect"}),t[1]||(t[1]=e("h4",{id:"사용-방법",tabindex:"-1"},[s("사용 방법 "),e("a",{class:"header-anchor",href:"#사용-방법","aria-label":'Permalink to "사용 방법"'},"​")],-1)),r(d,{id:"program-vision-connect"}),t[2]||(t[2]=a('<h3 id="물체-위치-읽기-설정하기" tabindex="-1">물체 위치 읽기 설정하기 <a class="header-anchor" href="#물체-위치-읽기-설정하기" aria-label="Permalink to &quot;물체 위치 읽기 설정하기&quot;">​</a></h3><p>연결 생성이 들어 있는 프로그램에 비전을 한 번 더 추가해 물체 위치를 읽도록 설정하는 과정입니다.</p><ol><li>트리의 빈 영역을 눌러 위치를 정하고 편집 아이콘으로 명령어 목록을 연 뒤 <strong>비전</strong>을 한 번 더 추가합니다.</li><li>새로 추가된 비전의 설정 화면을 열고, 함수 목록을 <strong>트리거 &amp; 자세 읽기</strong>로 바꿉니다.</li><li>반환 변수명에 <code>poses</code>를 입력하고 <strong>저장</strong>하면 두 번째 비전 옆에 <code>[Trigger &amp; Read Pose]</code>가 표시됩니다.</li></ol>',3)),r(o,{id:"program-vision-read"}),t[3]||(t[3]=e("h4",{id:"사용-방법-1",tabindex:"-1"},[s("사용 방법 "),e("a",{class:"header-anchor",href:"#사용-방법-1","aria-label":'Permalink to "사용 방법"'},"​")],-1)),r(d,{id:"program-vision-read"})])}const v=i(p,[["render",m]]);export{I as __pageData,v as default};
